<script lang="ts">
 import { onMount } from 'svelte';
 import { request, uploadFile } from './api';
 import { AlertBanner, PageHeader, RefreshButton } from './ui';
 type Message={id:string;body:string;author_name:string;created_at:string;file_id:string|null};type Thread={id:string;title:string;kind:string;unread:boolean;messages:Message[]};
 let threads=$state<Thread[]>([]),selected=$state(''),body=$state(''),attachment=$state<File|null>(null),busy=$state(false),loading=$state(true),error=$state(''),notice=$state('');let active=$derived(threads.find(x=>x.id===selected)??threads[0]);
 async function load(){loading=true;try{threads=await request<Thread[]>('/v1/collaboration');if(!selected)selected=threads[0]?.id??'';}catch(cause){error=cause instanceof Error?cause.message:'Inbox tidak dapat dimuat.';}finally{loading=false;}}
 async function open(id:string){selected=id;try{await request(`/v1/collaboration/${id}/read`,{method:'POST'});threads=threads.map(thread=>thread.id===id?{...thread,unread:false}:thread);}catch(cause){error=cause instanceof Error?cause.message:'Status baca tidak dapat diperbarui.';}}
 async function send(){if(!active||!body.trim())return;busy=true;error='';try{let file_id:string|null=null;if(attachment){const data_base64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=reject;reader.readAsDataURL(attachment!);});file_id=(await uploadFile({file_name:attachment.name,content_type:attachment.type||'application/octet-stream',data_base64})).id;}await request(`/v1/collaboration/${active.id}/messages`,{method:'POST',body:JSON.stringify({body,file_id})});body='';attachment=null;notice='Pesan terkirim.';await load();}catch(cause){error=cause instanceof Error?cause.message:'Pesan tidak dapat dikirim. Coba lagi.';}finally{busy=false;}}
 onMount(()=>{void load();const stream=new EventSource('/v1/events/stream');stream.addEventListener('pulse',()=>void load());stream.onerror=()=>{};return()=>stream.close();});
</script>
<main class="workspace-page"><PageHeader title="Inbox kolaborasi" description="Pesan kerja pribadi. Pembaruan otomatis berjalan setiap 15 detik." backHref="/app/today"/>{#if error}<AlertBanner variant="error">{error}</AlertBanner>{/if}{#if notice}<AlertBanner variant="success">{notice}</AlertBanner>{/if}<div class="layout"><nav class="panel" aria-label="Daftar ruang">{#each threads as item (item.id)}<button class:active={active?.id===item.id} onclick={()=>void open(item.id)}><strong>{item.title}</strong><small>{item.kind}{item.unread?' · Pesan baru':''}</small></button>{:else}<p class="muted">{loading?'Memuat percakapan…':'Belum ada ruang.'}</p>{/each}</nav><section class="panel">{#if active}<header><div><h2>{active.title}</h2><p>Pesan dibaca saat ruang ini dibuka.</p></div><RefreshButton onclick={load} label="Muat ulang"/></header><div class="messages" aria-live="polite">{#each active.messages as message (message.id)}<article><strong>{message.author_name}</strong><p>{message.body}</p>{#if message.file_id}<small>Lampiran tersedia di Berkas.</small>{/if}<small>{new Date(message.created_at).toLocaleString('id-ID')}</small></article>{:else}<p class="muted">Belum ada pesan.</p>{/each}</div><form novalidate onsubmit={(event)=>{event.preventDefault();void send();}}><label>Pesan<textarea bind:value={body} placeholder="Tulis pesan untuk ruang ini" required></textarea></label><label>Lampiran opsional<input type="file" onchange={(event)=>attachment=event.currentTarget.files?.[0]??null}/>{#if attachment}<small>{attachment.name}</small>{/if}</label><button disabled={busy}>{busy?'Mengirim…':'Kirim pesan'}</button></form>{/if}</section></div></main>
<style>.workspace-page,.layout{display:grid;gap:var(--space-4)}.layout{grid-template-columns:280px 1fr}.panel{display:grid;gap:var(--space-3);padding:var(--space-4);border-radius:var(--radius)}nav{align-content:start}nav button{text-align:left;background:var(--surface-alt);color:var(--text);border:1px solid var(--line)}nav button.active{border-color:var(--accent)}small,p{display:block;margin:0;color:var(--muted);font-size:var(--text-sm)}header{display:flex;align-items:start;justify-content:space-between;gap:var(--space-3)}.messages{display:grid;gap:var(--space-2);max-height:440px;overflow:auto}article{padding:var(--space-3);border:1px solid var(--line);border-radius:var(--radius-sm)}article p{margin:5px 0}form,label{display:grid;gap:8px}form{margin-top:var(--space-2)}textarea{min-height:90px}@media(max-width:720px){.layout{grid-template-columns:1fr}header{flex-direction:column;align-items:stretch}}</style>
